ST.xhtml:p:
RTrigger1(CLK := bSustain4Home);
RTrigger2(CLK := bSustain5Home);
RTrigger3(CLK := bSustain6Home);
RTrigger4(CLK := bSustain7Home);

IF RTrigger1.Q THEN
    nSustain4HomeState := 1;
    g_bSustain4HomeDone := FALSE;
    bSustain4Home := FALSE;
END_IF;
IF RTrigger2.Q THEN
    nSustain5HomeState := 1;
    g_bSustain5HomeDone := FALSE;
    bSustain5Home := FALSE;
END_IF;
IF RTrigger3.Q THEN
    nSustain6HomeState := 1;
    g_bSustain6HomeDone := FALSE;
    bSustain6Home := FALSE;
END_IF;
IF RTrigger4.Q THEN
    nSustain7HomeState := 1;
    g_boAntiRejection2HomeDone := FALSE;
    bSustain7Home := FALSE;
END_IF;

CASE nSustain4HomeState OF
  0:
    nSustain4HomeState := 0;
  1:
    g_Sustain4Home.Execute := TRUE;
    g_Sustain4Home.Position := dSustain4HomePosition;
    g_Sustain4Home.bCalibrationCam := g_bSusTain4HomeCal;
    g_Sustain4Home.DISTANCE := dSustain4HomeOffset;
    IF nSustain4HomeMode = 0 THEN
      g_Sustain4Home.HomingMode := 0;
    ELSIF nSustain4HomeMode = 1 THEN
      g_Sustain4Home.HomingMode := 5;
    ELSIF nSustain4HomeMode = 3 THEN
      g_Sustain4Home.HomingMode := 1;
    END_IF;

    IF g_Sustain4Home.Done THEN
      g_Sustain4Home.Execute := FALSE;
      g_bSustain4HomeDone := TRUE;
      nSustain4HomeState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nSustain4HomeState := 20;
    END_IF;
    IF g_Sustain4Home.CommandAborted OR g_Sustain4Home.Error THEN
      g_Sustain4Home.Execute := FALSE;
      nSustain4HomeState := 0;
    END_IF;
  20:
    g_Sustain4Home.Execute := FALSE;
    g_Sustain4Stop.Execute := TRUE;
    IF g_Sustain4Stop.Done AND g_bPlcStartBuffer THEN
      g_Sustain4Stop.Execute := FALSE;
      nSustain4HomeState := 1;
    END_IF;
    IF g_Sustain4Stop.CommandAborted OR g_Sustain4Stop.Error THEN
      g_Sustain4Stop.Execute := FALSE;
      nSustain4HomeState := 0;
    END_IF;
END_CASE;

CASE nSustain5HomeState OF
  0:
    nSustain5HomeState := 0;
  1:
    g_Sustain5Home.Execute := TRUE;
    g_Sustain5Home.Position := dSustain5HomePosition;
    g_Sustain5Home.bCalibrationCam := g_bSusTain5HomeCal;
    g_Sustain5Home.DISTANCE := dSustain5HomeOffset;
    IF nSustain5HomeMode = 0 THEN
      g_Sustain5Home.HomingMode := 0;
    ELSIF nSustain5HomeMode = 1 THEN
      g_Sustain5Home.HomingMode := 5;
     ELSIF nSustain5HomeMode = 3 THEN
      g_Sustain5Home.HomingMode := 1;  
    END_IF;
    IF g_Sustain5Home.Done THEN
      g_Sustain5Home.Execute := FALSE;
      g_bSustain5HomeDone := TRUE;
      nSustain5HomeState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nSustain5HomeState := 20;
    END_IF;
    IF g_Sustain5Home.CommandAborted OR g_Sustain5Home.Error THEN
      g_Sustain5Home.Execute := FALSE;
      nSustain5HomeState := 0;
    END_IF;
  20:
    g_Sustain5Home.Execute := FALSE;
    g_Sustain5Stop.Execute := TRUE;
    IF g_Sustain5Stop.Done AND g_bPlcStartBuffer THEN
      g_Sustain5Stop.Execute := FALSE;
      nSustain5HomeState := 1;
    END_IF;
    IF g_Sustain5Stop.CommandAborted OR g_Sustain5Stop.Error THEN
      g_Sustain5Stop.Execute := FALSE;
      nSustain5HomeState := 0;
    END_IF;
END_CASE;

