  1:
    g_Sustain6Home.Execute := TRUE;
    g_Sustain6Home.Position := dSustain6HomePosition;
    g_Sustain6Home.bCalibrationCam := g_bSusTain6HomeCal;
    g_Sustain6Home.DISTANCE := dSustain6HomeOffset;
    IF nSustain6HomeMode = 0 THEN
      g_Sustain6Home.HomingMode := 0;
    ELSIF nSustain6HomeMode = 1 THEN
